{
  "version": "2.1.0",
  "$schema": "https://json.schemastore.org/sarif-2.1.0.json",
  "runs": [
    {
      "properties": {
        "programming_model": "v2",
        "target_python": "3.12",
        "deployment_mode": "remote-build",
        "hosting_plan": null,
        "gate_failed": false
      },
      "tool": {
        "driver": {
          "name": "azure-functions-doctor",
          "version": "0.23.1",
          "informationUri": "https://github.com/yeongseon/azure-functions-doctor-python",
          "rules": [
            {
              "id": "check_programming_model_v2",
              "name": "Programming model v2",
              "shortDescription": {
                "text": "Confirms the project uses the Azure Functions Python v2 decorator-based programming model (via @app. or @bp. decorators)."
              },
              "properties": {
                "category": "project_structure",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python?pivots=python-mode-decorators"
            },
            {
              "id": "check_blueprint_registration",
              "name": "Blueprint registration",
              "shortDescription": {
                "text": "Warns when a Blueprint has decorators but is never registered on the FunctionApp."
              },
              "properties": {
                "category": "project_structure",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python?pivots=python-mode-decorators"
            },
            {
              "id": "check_python_version",
              "name": "Python version",
              "shortDescription": {
                "text": "Checks that the target Python version is analyzable by Doctor (3.10\u20133.14); lifecycle support is checked separately."
              },
              "properties": {
                "category": "environment",
                "required": true,
                "tier": "core",
                "severity": "error"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python#supported-python-versions"
            },
            {
              "id": "check_python_runtime_lifecycle",
              "name": "Python runtime lifecycle",
              "shortDescription": {
                "text": "Checks the target Python version against its published Azure Functions end-of-support date, warning on a retiring runtime and failing on one past end-of-support."
              },
              "properties": {
                "category": "environment",
                "required": false,
                "tier": "core",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/supported-languages"
            },
            {
              "id": "check_venv",
              "name": "Virtual environment",
              "shortDescription": {
                "text": "Checks if a virtual environment is activated (venv, conda, or uv)."
              },
              "properties": {
                "category": "environment",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-best-practices?tabs=python#use-virtual-environments"
            },
            {
              "id": "check_functions_runtime_lifecycle",
              "name": "Functions runtime lifecycle",
              "shortDescription": {
                "text": "Checks the Azure Functions runtime major version (FUNCTIONS_EXTENSION_VERSION) for a Python app: v1 is incompatible with Python, v2/v3 are out of support, v3 on Linux Consumption stops running on a published date, and v4 is the current GA runtime."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "core",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/functions-versions"
            },
            {
              "id": "check_python_executable",
              "name": "Python executable",
              "shortDescription": {
                "text": "Checks if the Python executable path exists."
              },
              "properties": {
                "category": "environment",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python#python-version-and-package-management"
            },
            {
              "id": "check_hosting_plan_lifecycle",
              "name": "Hosting plan lifecycle",
              "shortDescription": {
                "text": "Checks the resolved hosting plan against its published retirement date, informing on a distant retirement, warning inside the retiring-soon window, and failing once the plan has retired."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "core",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/migration/migrate-plan-consumption-to-flex"
            },
            {
              "id": "check_requirements_txt",
              "name": "requirements.txt",
              "shortDescription": {
                "text": "Checks that dependencies are declared for the deployment mode: requirements.txt for remote build, or pyproject.toml for a local/prebuilt build."
              },
              "properties": {
                "category": "dependencies",
                "required": true,
                "tier": "core",
                "severity": "error"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python#managing-dependencies"
            },
            {
              "id": "check_flex_runtime_config",
              "name": "Flex Consumption runtime config",
              "shortDescription": {
                "text": "For a Flex Consumption app, validates the runtime declared under functionAppConfig.runtime (name/version) against the supported Python versions, and warns when a legacy linuxFxVersion is present (Flex ignores it)."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "core",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/flex-consumption-plan"
            },
            {
              "id": "check_azure_functions_library",
              "name": "azure-functions package",
              "shortDescription": {
                "text": "Checks that the azure-functions package is installable for the deployment mode (requirements.txt for remote build, pyproject.toml for local/prebuilt)."
              },
              "properties": {
                "category": "dependencies",
                "required": true,
                "tier": "core",
                "severity": "error"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python"
            },
            {
              "id": "check_flex_deprecated_settings",
              "name": "Flex Consumption deprecated app settings",
              "shortDescription": {
                "text": "For a Flex Consumption app, warns when legacy app settings that Flex ignores are declared (worker-runtime selection, Oryx/remote-build toggles, Azure Files content-share settings, run-from-package, and VNet route-all), citing the replacement mechanism for each."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "core",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/functions-app-settings"
            },
            {
              "id": "check_native_dependency_risk",
              "name": "Native dependency risk",
              "shortDescription": {
                "text": "Warns when requirements.txt includes packages with native extensions that often require platform-matching Linux builds."
              },
              "properties": {
                "category": "dependencies",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python#remote-build"
            },
            {
              "id": "check_flex_deployment_storage",
              "name": "Flex Consumption deployment storage",
              "shortDescription": {
                "text": "For a Flex Consumption app, validates the deployment storage shape declared under functionAppConfig.deployment.storage: a container URL must be specified and authentication must be configured (managed identity or a named storage account connection string). Skips gracefully when infra declares no deployment storage block."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "core",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/flex-consumption-plan"
            },
            {
              "id": "check_azure_functions_worker",
              "name": "azure-functions-worker not pinned",
              "shortDescription": {
                "text": "Warns if azure-functions-worker is directly declared in requirements.txt. The Azure Functions platform manages the worker runtime; pinning it can cause deployment failures."
              },
              "properties": {
                "category": "dependencies",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python#managing-dependencies"
            },
            {
              "id": "check_host_json",
              "name": "host.json",
              "shortDescription": {
                "text": "Checks if host.json exists at the project root."
              },
              "properties": {
                "category": "structure",
                "required": true,
                "tier": "core",
                "severity": "error"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-host-json"
            },
            {
              "id": "check_binding_connection_resolution",
              "name": "Binding connection resolution",
              "shortDescription": {
                "text": "Extracts connection= references from v2 trigger/binding decorators (Storage, Service Bus, Event Hub, Cosmos DB, and any binding exposing a connection keyword) and resolves each against local.settings.json Values plus ingested deploy-config app settings. Warns when a referenced connection has no corresponding configuration; identity-based connection groups (<name>__...) are treated as configured."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "core",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/functions-reference#connections"
            },
            {
              "id": "check_host_json_version",
              "name": "host.json version",
              "shortDescription": {
                "text": "Checks that host.json declares \"version\": \"2.0\" as required by the v2 runtime."
              },
              "properties": {
                "category": "structure",
                "required": true,
                "tier": "core",
                "severity": "error"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-host-json"
            },
            {
              "id": "check_local_settings",
              "name": "local.settings.json",
              "shortDescription": {
                "text": "Checks if local.settings.json exists for local development."
              },
              "properties": {
                "category": "structure",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              }
            },
            {
              "id": "check_func_cli",
              "name": "Azure Functions Core Tools (func)",
              "shortDescription": {
                "text": "Checks if Azure Functions Core Tools is available on PATH."
              },
              "properties": {
                "category": "tooling",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-run-local#v4"
            },
            {
              "id": "check_func_core_tools_version",
              "name": "Azure Functions Core Tools version",
              "shortDescription": {
                "text": "Checks if Azure Functions Core Tools meets the minimum supported version."
              },
              "properties": {
                "category": "tooling",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-run-local#v4"
            },
            {
              "id": "check_durabletask_config",
              "name": "Durable Functions configuration",
              "shortDescription": {
                "text": "Checks for durableTask configuration in host.json when durable functions are present."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/durable/durable-functions-overview"
            },
            {
              "id": "check_app_insights",
              "name": "Application Insights configuration",
              "shortDescription": {
                "text": "Checks that Application Insights uses a connection string (support for instrumentation-key-based global ingestion ended 2025-03-31)."
              },
              "properties": {
                "category": "telemetry",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-monitor/app/migrate-from-instrumentation-keys-to-connection-strings"
            },
            {
              "id": "check_extension_bundle",
              "name": "extensionBundle",
              "shortDescription": {
                "text": "Checks whether extensionBundle is configured in host.json."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/extension-bundles"
            },
            {
              "id": "check_asgi_wsgi_exposure",
              "name": "ASGI/WSGI compatibility",
              "shortDescription": {
                "text": "Detects whether the project exposes an ASGI or WSGI callable."
              },
              "properties": {
                "category": "framework",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/functions-reference-python#asgi"
            },
            {
              "id": "check_unused_files",
              "name": "Detect unused or invalid files",
              "shortDescription": {
                "text": "Detects common unwanted files in the project root or deployment package."
              },
              "properties": {
                "category": "project_health",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              }
            },
            {
              "id": "check_funcignore",
              "name": ".funcignore",
              "shortDescription": {
                "text": "Checks if a .funcignore file is present to control what gets deployed."
              },
              "properties": {
                "category": "project_health",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-run-local#funcignore"
            },
            {
              "id": "check_local_settings_git_tracked",
              "name": "local.settings.json not git-tracked",
              "shortDescription": {
                "text": "Checks that local.settings.json is not tracked by git, which could expose secrets in version control."
              },
              "properties": {
                "category": "project_health",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-develop-local#local-settings-file"
            },
            {
              "id": "check_extension_bundle_v4",
              "name": "extensionBundle v4 recommended",
              "shortDescription": {
                "text": "Checks that extensionBundle in host.json uses the recommended v4 version range [4.*, 5.0.0)."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/azure/azure-functions/extension-bundles"
            },
            {
              "id": "check_decorator_order",
              "name": "Decorator order",
              "shortDescription": {
                "text": "Warns when @validate_http is stacked outside @with_context. The correct order (top to bottom) is @app.route -> @with_context -> @validate_http."
              },
              "properties": {
                "category": "framework",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://yeongseon.dev/azure-functions-python/platform/how-the-worker-binds-handlers/#binding"
            },
            {
              "id": "check_endpoint_metadata",
              "name": "Endpoint metadata coverage",
              "shortDescription": {
                "text": "Warns when HTTP route handlers in a project that depends on azure-functions-validation lack @validate_http, meaning they will not emit endpoint OpenAPI metadata."
              },
              "properties": {
                "category": "framework",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://yeongseon.dev/azure-functions-python/platform/how-the-worker-binds-handlers/#binding"
            },
            {
              "id": "check_openapi_version_mixing",
              "name": "OpenAPI version consistency",
              "shortDescription": {
                "text": "Warns when a project mixes OpenAPI 3.0 signals (3.0.x version strings or nullable keyword) with OpenAPI 3.1 signals (3.1.x version strings), which produces inconsistent generated specs."
              },
              "properties": {
                "category": "framework",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              }
            },
            {
              "id": "check_scan_before_spec",
              "name": "Endpoint scan before spec build",
              "shortDescription": {
                "text": "Warns when the OpenAPI spec is built before endpoints are scanned/registered, or when a spec is built without any endpoint scan, producing an empty or incomplete spec."
              },
              "properties": {
                "category": "framework",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              }
            },
            {
              "id": "check_langgraph_anonymous_auth",
              "name": "LangGraph route authentication",
              "shortDescription": {
                "text": "Warns when a project that imports langgraph exposes HTTP routes with auth_level set to ANONYMOUS, leaving graph endpoints publicly reachable."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              }
            },
            {
              "id": "check_durable_nondeterminism",
              "name": "Orchestrator determinism",
              "shortDescription": {
                "text": "Fails when orchestration trigger functions call nondeterministic APIs (datetime.now, random, uuid, requests, open, os.getenv), which breaks Durable Functions replay."
              },
              "properties": {
                "category": "framework",
                "required": true,
                "tier": "core",
                "severity": "error"
              }
            },
            {
              "id": "check_otel_trace_context_activation",
              "name": "OTel trace-context activation",
              "shortDescription": {
                "text": "Warns when a project opts into azure-functions-logging trace-context activation (activate_trace_context=True or set_default_trace_context_activation) but does not declare an opentelemetry dependency, so activation silently no-ops at runtime."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://yeongseon.dev/azure-functions-python/logging/opentelemetry/"
            },
            {
              "id": "check_functions_extension_version",
              "name": "Functions extension version",
              "shortDescription": {
                "text": "Flags a missing, legacy, or non-~4 FUNCTIONS_EXTENSION_VERSION in local.settings.json so the app targets the supported v4 Azure Functions runtime."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-versions"
            },
            {
              "id": "check_linux_fx_version",
              "name": "Linux runtime (linuxFxVersion)",
              "shortDescription": {
                "text": "Validates any Python linuxFxVersion declared in infra (bicep) config so Flex Consumption / Linux plan apps target a supported Python runtime."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python#supported-python-versions"
            },
            {
              "id": "check_host_json_log_level_conflict",
              "name": "host.json logLevel conflict",
              "shortDescription": {
                "text": "Flags host.json logging.logLevel category overrides that are more verbose than the configured default, which silently increases log volume, cost, and PII exposure."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-host-json#logging"
            },
            {
              "id": "check_dev_storage_connection",
              "name": "Dev-storage emulator connection",
              "shortDescription": {
                "text": "Flags AzureWebJobsStorage=UseDevelopmentStorage=true in deployable infra config (bicep/ARM), which points at the local Azurite emulator and must never ship to a deployed app."
              },
              "properties": {
                "category": "configuration",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-app-settings#azurewebjobsstorage"
            },
            {
              "id": "check_unpinned_requirements",
              "name": "Pinned requirements",
              "shortDescription": {
                "text": "Warns when requirements.txt declares dependencies with no version specifier or an unbounded lower bound, making Azure remote-build deployments non-reproducible."
              },
              "properties": {
                "category": "dependencies",
                "required": false,
                "tier": "extended",
                "severity": "warning"
              },
              "helpUri": "https://learn.microsoft.com/en-us/azure/azure-functions/functions-reference-python#package-management"
            }
          ]
        }
      },
